/**
 * rust-node-rate-limit — public API (TypeScript).
 *
 * This layer re-exports the native `RateLimiter` class (generated from Rust by
 * napi-rs) and its types. The framework adapters (Express, Fastify, NestJS) are
 * imported from the package subpaths.
 *
 * "Ultra-fast rate limiting for Node.js powered by Rust."
 */

// Namespace import: works the same in CommonJS and ESM when consuming the
// native addon (a CJS module generated by napi-rs).
import * as native from "../binding.js";

export type {
  CheckResult,
  RateLimitStats,
  RateLimiterOptions,
} from "../binding.js";

/** Sanity check: returns "Hello from Rust" from the native core. */
export const hello: () => string = native.hello;

/**
 * Local (in-process) rate limiter with Fixed Window and Sliding Window algorithms and a Rust core.
 *
 * ```ts
 * import { RateLimiter } from "rust-node-rate-limit";
 *
 * const limiter = new RateLimiter({ limit: 100, windowSeconds: 60 });
 * limiter.allow("user:123");      // true / false
 * limiter.check("user:123");      // { allowed, limit, remaining, retryAfter, resetAfter }
 * ```
 */
export const RateLimiter = native.RateLimiter;

/** Instance type of {@link RateLimiter}. */
export type RateLimiter = InstanceType<typeof native.RateLimiter>;
